// Embed the pinned KaTeX parser into the plain-JS client bundle. MathML output
// uses the browser's math layout, so no runtime npm resolution, CDN, CSS or fonts
// are needed. Run pnpm install --ignore-scripts, then pnpm run build:math.
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const require = createRequire(import.meta.url)
const root = fileURLToPath(new URL('../', import.meta.url))
const dist = path.dirname(require.resolve('katex'))
const manifest = JSON.parse(await readFile(path.join(dist, '../package.json'), 'utf8'))
const project = JSON.parse(await readFile(path.join(root, 'package.json'), 'utf8'))
assert.equal(manifest.version, project.devDependencies.katex, 'Install the pinned KaTeX version before building')
const library = (await readFile(path.join(dist, 'katex.min.js'), 'utf8')).replace(/\n?\/\/# sourceMappingURL=.*(?:\r?\n)?$/, '').trim()
const hash = createHash('sha256').update(library).digest('hex')
const start = '    // #region bundled-katex (generated by scripts/build-math.mjs)'
const end = '    // #endregion bundled-katex'
const region = `${start}
    // KaTeX ${manifest.version} (MIT); source sha256 ${hash}. See vendor/katex-LICENSE.
    const latexEngine = (() => {
      const module = { exports: {} }
      const exports = module.exports
${library}
      return module.exports
    })()
${end}`
const target = path.join(root, 'client.js')
const before = await readFile(target, 'utf8')
const from = before.indexOf(start)
let after
if (from >= 0) {
  const to = before.indexOf(end, from)
  assert.ok(to > from, 'bundled-katex region must have an end marker')
  after = before.slice(0, from) + region + before.slice(to + end.length)
} else {
  const anchor = '  factory(require) {\n'
  assert.equal(before.split(anchor).length, 2, 'Client factory anchor must be unique')
  after = before.replace(anchor, () => `${anchor}${region}\n\n`)
}
if (after !== before) await writeFile(target, after, 'utf8')
await mkdir(path.join(root, 'vendor'), { recursive: true })
const license = await readFile(path.join(dist, '../LICENSE'), 'utf8')
await writeFile(path.join(root, 'vendor/katex-LICENSE'), license, 'utf8')
console.log(`Bundled KaTeX ${manifest.version}: ${Buffer.byteLength(library)} bytes; MathML only at runtime`)
